# Name-meaning lookup - run with: python3 demo.py
# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMO-000001",
    "name": "Jagannath ଜଗନ୍ନାଥ",
    "kind": "first-name",
    "meaning": "Jagannath (ଜଗନ୍ନାଥ) is a masculine given name in Odia. Meaning: Lord of the universe. The presiding deity of Puri; a lea"
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Jag")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

